from .measurement_exceptions import EventNotFoundException
import ast


class Verifications(object):
    @staticmethod
    def verify_that_measurement_configuration_has_frequencies_in_specified_order(meas_order, frequencies):
        """
        Verifies that measurement order is as specified
        :param meas_order:
        :param frequencies:
        :return:
        """
        result = []
        if len(meas_order) != len(frequencies):
            raise AssertionError(
                "Configured measurement frequencies and given order have different length ({}!={})".format(
                    len(meas_order), len(frequencies)
                )
            )
        for i in range(max(len(meas_order), len(frequencies))):
            result.append(
                meas_order[i] in frequencies[i]
                if isinstance(frequencies[i], list)
                else meas_order[i] == frequencies[i]
            )
        if not all(result):
            raise AssertionError(
                "Configured measurements have order different than expected, {} != {} ({})".format(
                    repr(meas_order), repr(list(frequencies)), repr(result)
                )
            )

    @staticmethod
    def verify_that_specified_events_are_active_on_given_frequencies_and_have_specified_thresholds(
        meas_conf, event_type, event_params, frequencies
    ):
        """
        Checks if events are active on given frequencies and if they hace specific thresholds
        :param meas_conf:
        :param event_type:
        :param event_params: Dictionary containing event parameters, eg. {'Threshold': 'RSRP 35'}
        :param frequencies:
        :return:
        """
        if not isinstance(event_params, dict):
            event_params = ast.literal_eval(event_params)
        event_type = event_type.strip()
        if isinstance(frequencies, int):
            frequencies = [frequencies]
        results = (
            Verifications._verify_that_specified_events_are_active_on_given_frequencies_and_have_specified_thresholds(
                meas_conf, event_type, event_params, frequencies
            ))
        if not all(any(results[freq]) for freq in frequencies):
            raise AssertionError(
                '{} is not active on at least one frequency or does not have specified thresholds'.format(
                    repr(event_type)
                )
            )

    @staticmethod
    def _verify_that_specified_events_are_active_on_given_frequencies_and_have_specified_thresholds(
        meas_conf, event_type, event_params, frequencies
    ):
        report_ids = {}
        results = {}
        for freq in frequencies:
            report_ids[freq] = meas_conf.find_active_report_ids_on_frequency(freq, event_type)
            if freq in report_ids:
                results[freq] = [
                    meas_conf.report_conf_dict[report_id][event_type] == event_params for report_id in report_ids[freq]
                ]
        return results

    @staticmethod
    def verify_that_specified_events_are_active_on_given_frequencies_and_have_specified_trigger(
        meas_conf, event_type, trigger, frequencies
    ):
        """
        Checks if events are active on given frequencies and if they have specific trigger
        :param meas_conf:
        :param event_type:
        :param trigger:
        :param frequencies:
        :return:
        """
        if isinstance(frequencies, int):
            frequencies = [frequencies]
        report_ids = {}
        results = {}
        for freq in frequencies:
            report_ids[freq] = meas_conf.find_active_report_ids_on_frequency(freq, event_type)
            if freq in report_ids:
                results[freq] = [
                    meas_conf.report_conf_dict[report_id]['trigger'] == trigger.lower()
                    for report_id in report_ids[freq]
                ]
        if not all(any(results[freq]) for freq in frequencies):
            raise EventNotFoundException(
                '{} is not active on at least one frequency or is not triggered by {}'.format(event_type, trigger)
            )

    @staticmethod
    def verify_that_specified_events_are_active_on_given_frequencies(meas_conf, event_list, frequencies):
        """
        Checks if given events are active on given frequencies
        :param meas_conf:
        :param event_list: List of events that should be active eg. ["EventA3", "EventA5"].
                           Accepts single event string.
        :param frequencies:
        :return:
        """
        if not isinstance(event_list, list):
            event_list = [event_list]
        events = {}
        for freq in frequencies:
            events[freq] = meas_conf.get_events_active_on_frequency(freq)
        result = {}
        for freq in frequencies:
            result[freq] = [event in events[freq] for event in event_list]
        if not all(all(result[freq]) for freq in frequencies):
            raise AssertionError(
                'At least one of specified events ({}) is not active on at least one frequency, {}'.format(
                    repr(event_list), repr(events)
                )
            )
